define("UMBRAL_ESTANCIA",5);

require_once("includes/rutas.php");
require_once("libs/mysql.class.php");


$path="motor/caras/";
while(true){

    recorre_dir($path,1);
    sleep(1);
}


function recorre_dir($path,$nivel){
    $sql=new Conectar();
    $tmp=new Conectar();
    
    if($nivel==3){
        $archivos=[];
    }
    
    $dir = opendir($path);
    while ($elemento = readdir($dir)){
        if( $elemento != "." && $elemento != ".."){
            if( is_dir($path.$elemento) ){
                switch($nivel){
                    case 1:
                        $local_id=$elemento;
                        echo "<p><strong>local_id: ". $local_id ."</strong></p>\n";
                        if($local_id!="aux" and $local_id!="sinclasificar"){
                            recorre_dir($path.$local_id."/",2);
                        }
                        break;
                    case 2:
                        $persona=$elemento;
                        echo "<p><strong>persona: ". $persona ."</strong></p>\n";
                        recorre_dir($path.$persona,3);
                        break;
                    default:
                        echo "Esto no puede pasar\n";
                        break;
                }
                
            } else {
                
                
                
                
                $ruta=$path."/".$elemento;
                echo "Foto:". $ruta."\n";
                
                $archivos[]=$ruta;
                
 
            }
        }
    }   
    if($nivel==3){
        
        
        sort($archivos);
        
        foreach($archivos as $ruta){



            $aux= explode("/", $ruta);
            $local_id=$aux[2];
            $persona_original=$aux[3];
            $persona= str_replace("'", "", $persona_original);
            $file=$aux[4];
            $aux= explode("_", $file);
            $camara_id=$aux[0];
            $fecha=$aux[1];
            $resto=$aux[2];
            $resto2=$aux[3];
            $segs_pasados= str_replace(".avi", "", $resto2);
            $segs_pasados= str_replace(".jpg", "", $segs_pasados);
            $aux= explode(".", $segs_pasados);
            $segs_pasados=$aux[0];
            $aux= explode(".", $resto);
            $hora=$aux[0].".".$aux[1];
            $fecha_foto=$fecha." ".$hora;

            $aux=date($fecha_foto);
            $fecha_foto=strtotime('+'.$segs_pasados.' second', strtotime($aux));
            $fecha_foto=date('Y-m-d H:i:s',$fecha_foto);

            $aux=date($fecha_foto);
            $fecha_ultima=strtotime('-'.UMBRAL_ESTANCIA.' second', strtotime($aux));
            $fecha_ultima=date('Y-m-d H:i:s',$fecha_ultima);

            echo "\n==========================================\n";

            echo "Datos:\n";
            echo "local_id:".$local_id."\n";
            echo "persona:".$persona."\n";  //cod_interno
            echo "camara:".$camara_id."\n";  
            echo "fecha:".$fecha."\n";  //2021-07-09
            echo "hora:".$hora."\n";  //13:35:23.330041
            echo "segs_pasados:".$segs_pasados."\n";  //12.771470546722412.jpg
            echo "fecha_foto final:".$fecha_foto."\n";  
            echo "fecha reciente considerar nueva:".$fecha_ultima."\n\n";



            $mover_img=false;

            $persona= str_replace("'", "", $persona);
            $sql->Consultar ( "personas", "id", "cod_interno='".$persona."'", "id asc", false);
            if($sql->num==0){
                echo "No existe esta persona\n";

                $campos=["local_id","cod_interno"];
                $valores=[$local_id,$persona];
                $sql->Insertar("personas",$campos,$valores,true);
                $persona_id=$sql->id;

                echo "persona_id:".$persona_id."\n";

                $campos=["persona_id","camara_id","fecha_ini","fecha_fin"];
                $valores=[$persona_id,$camara_id,$fecha_foto,$fecha_foto];
                $sql->Insertar("estancias",$campos,$valores);
                $estancia_id=$sql->id;

                echo "estancia_id:".$estancia_id."\n";

                $mover_img=true;
            }else{
                echo "Esta persona ya existe\n";

                $persona_id=$sql->row["id"];

                echo "persona_id2:".$persona_id."\n";


                $sql->Consultar ( "estancias", 
                        "id,fecha_fin", 
                        "camara_id=".$camara_id." and fecha_fin>='".$fecha_ultima."' and fecha_fin<='".$fecha_foto."'", "id asc", false);
                if($sql->num>0){
                    echo "ya hay una estancia de hace menos de 5 segundos, su fecha es:".$sql->row["fecha_fin"]."\n";

                    if($fecha_foto>$sql->row["fecha_fin"]){
                        echo "amplio la estancia\n";

                        $sql->Actualizar("estancias",["fecha_fin"],[$fecha_foto],"id=".$sql->row["id"]);
                        $mover_img=true;
                        $estancia_id=$sql->row["id"];

                        echo "estancia_id:".$estancia_id."\n";
                        
                        echo "como he ampliado elimino las anteriores fotos excepto la 1º\n";
                        $sql->Consultar("fotos","id","estancia_id=".$estancia_id,"id asc", true);
                        
                        if($sql->num>1){
                            $primera=true;
                            do{
                                if($primera){
                                    $primera=false;
                                }else{
                                    $cmd="rm motor/caras_procesadas/".$sql->row["id"].".jpg";
                                    echo $cmd."\n";
                                    exec($cmd);
                                    $tmp->Eliminar("fotos", "id=".$sql->row["id"]);
                                }
                            }while($sql->Siguiente());
                        }
                        
                        
                    }
                }else{
                    echo "No hay estancia de hace 5 segundos\n";

                    $campos=["persona_id","camara_id","fecha_ini","fecha_fin"];
                    $valores=[$persona_id,$camara_id,$fecha_foto,$fecha_foto];
                    $sql->Insertar("estancias",$campos,$valores);
                    $mover_img=true;
                    $estancia_id=$sql->id;

                    echo "estancia_id2:".$estancia_id."\n";
                }



            }

            if($mover_img){
                echo "Inserto foto\n";
                $sql->Insertar("fotos",["estancia_id"],[$estancia_id]);
                $cmd="mv \"".$ruta."\" motor/caras_procesadas/".$sql->id.".jpg";
                echo $cmd."\n";
                exec($cmd);
            }else{
                $cmd="rm \"".$ruta."\"";
                echo $cmd."\n";
                exec($cmd);
            }

            echo "\n==========================================\n";


        }
        
        
    }
    
}